-- Derived from the state animation IDs embedded in each local Nitro furniture bundle.
-- Currency 103 is the imported star currency; expose those offers as diamonds (type 5).
UPDATE `catalog_pages` SET `parent_id`=-1, `min_rank`=1, `visible`='1', `enabled`='1' WHERE `id`=1800;
UPDATE `catalog_items` SET `points_type`=5 WHERE `cost_points`>0 AND `points_type`=103;

DROP TEMPORARY TABLE IF EXISTS `nitro_furni_states`;
CREATE TEMPORARY TABLE `nitro_furni_states` (`item_name` VARCHAR(255) NOT NULL PRIMARY KEY, `state_count` INT NOT NULL);
UPDATE `items_base` item JOIN `nitro_furni_states` state ON LOWER(item.`item_name`)=state.`item_name`
SET item.`interaction_modes_count`=state.`state_count`;
DROP TEMPORARY TABLE `nitro_furni_states`;
